contracts/core/Escrow.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";

/**
 * @title Escrow
 * @notice Milestone-based escrow for high-value B2B transactions
 *
 * Use Case: DR Central Bank $3B frozen funds
 * - Depositor: DR Central Bank ($3B USDC)
 * - Beneficiary: Recipient entity
 * - Milestones: [Shipment, Delivery, Verification, etc.]
 * - Each milestone releases a percentage of escrowed funds
 *
 * Security Features:
 * - Segregated custody (each escrow is isolated)
 * - Multi-sig control (2-of-3 required for releases)
 * - Time-locks (24h delay on large withdrawals)
 * - Dispute resolution (arbitrator can intervene)
 * - Emergency pause (freeze all escrows if needed)
 *
 * Fee Structure:
 * - Escrow service fee: 0.5% of escrowed amount (one-time)
 * - Success fee: 25% of unfrozen amount (if applicable)
 */
contract Escrow is AccessControl, ReentrancyGuard, Pausable {
    using SafeERC20 for IERC20;

    // ============================================
    // ROLES
    // ============================================

    bytes32 public constant ORACLE_ROLE = keccak256("ORACLE_ROLE");
    bytes32 public constant PAUSER_ROLE = keccak256("PAUSER_ROLE");
    bytes32 public constant ARBITRATOR_ROLE = keccak256("ARBITRATOR_ROLE");

    // ============================================
    // ENUMS
    // ============================================

    enum EscrowStatus {
        Pending,        // Awaiting deposit
        Active,         // Funds escrowed, milestones in progress
        Completed,      // All milestones done, funds released
        Disputed,       // Dispute raised
        Cancelled,      // Escrow cancelled
        Expired         // Expired without completion
    }

    // ============================================
    // STRUCTS
    // ============================================

    struct Milestone {
        string description;
        uint256 percentage;     // Basis points (10000 = 100%)
        bool completed;
        uint256 completedAt;
    }

    struct EscrowDetails {
        // Parties
        address depositor;
        address beneficiary;
        address arbitrator;

        // Token
        IERC20 token;           // USDC or GRAIN

        // Amounts
        uint256 totalAmount;
        uint256 releasedAmount;
        uint256 escrowFee;      // 0.5% service fee

        // Status
        EscrowStatus status;

        // Milestones
        Milestone[] milestones;

        // Timestamps
        uint256 createdAt;
        uint256 depositedAt;
        uint256 expiresAt;
        uint256 completedAt;

        // Deal metadata
        string dealId;          // External reference (e.g., "DR-$3B-2025")
        string dealDescription;
    }

    // ============================================
    // STATE VARIABLES
    // ============================================

    // Escrow ID counter
    uint256 public nextEscrowId = 1;

    // All escrows
    mapping(uint256 => EscrowDetails) public escrows;

    // Escrow service fee (basis points)
    // 50 = 0.5%
    uint256 public escrowFeePercent = 50;

    // Fee collector address
    address public feeCollector;

    // Withdrawal time-lock (24 hours)
    uint256 public constant WITHDRAWAL_DELAY = 24 hours;

    // Pending withdrawals (for time-lock)
    mapping(uint256 => uint256) public pendingWithdrawals;

    // ============================================
    // EVENTS
    // ============================================

    event EscrowCreated(
        uint256 indexed escrowId,
        address indexed depositor,
        address indexed beneficiary,
        address token,
        uint256 totalAmount,
        string dealId
    );

    event EscrowFunded(
        uint256 indexed escrowId,
        uint256 amount,
        uint256 escrowFee
    );

    event MilestoneCompleted(
        uint256 indexed escrowId,
        uint256 milestoneIndex,
        uint256 amountReleased,
        address indexed beneficiary
    );

    event EscrowCompleted(
        uint256 indexed escrowId,
        uint256 totalReleased
    );

    event EscrowDisputed(
        uint256 indexed escrowId,
        address indexed disputedBy,
        string reason
    );

    event DisputeResolved(
        uint256 indexed escrowId,
        uint256 depositorAmount,
        uint256 beneficiaryAmount
    );

    event EscrowCancelled(
        uint256 indexed escrowId,
        uint256 refundedAmount
    );

    event WithdrawalScheduled(
        uint256 indexed escrowId,
        uint256 executeAt
    );

    // ============================================
    // CONSTRUCTOR
    // ============================================

    constructor(address admin, address _feeCollector) {
        require(admin != address(0), "Invalid admin");
        require(_feeCollector != address(0), "Invalid fee collector");

        _grantRole(DEFAULT_ADMIN_ROLE, admin);
        _grantRole(PAUSER_ROLE, admin);
        _grantRole(ORACLE_ROLE, admin); // Can complete milestones
        _grantRole(ARBITRATOR_ROLE, admin); // Can resolve disputes

        feeCollector = _feeCollector;
    }

    // ============================================
    // CORE FUNCTIONS
    // ============================================

    /**
     * @notice Create a new escrow
     * @param beneficiary Recipient of escrowed funds
     * @param token ERC20 token address (USDC or GRAIN)
     * @param totalAmount Total amount to escrow
     * @param milestoneDescriptions Array of milestone descriptions
     * @param milestonePercentages Array of milestone percentages (basis points)
     * @param expirationDays Days until escrow expires
     * @param dealId External deal reference
     * @param dealDescription Deal details
     * @return escrowId The created escrow ID
     */
    function createEscrow(
        address beneficiary,
        address arbitrator,
        address token,
        uint256 totalAmount,
        string[] memory milestoneDescriptions,
        uint256[] memory milestonePercentages,
        uint256 expirationDays,
        string memory dealId,
        string memory dealDescription
    ) external whenNotPaused nonReentrant returns (uint256) {
        require(beneficiary != address(0), "Invalid beneficiary");
        require(token != address(0), "Invalid token");
        require(totalAmount > 0, "Invalid amount");
        require(milestoneDescriptions.length == milestonePercentages.length, "Milestone mismatch");
        require(milestoneDescriptions.length > 0, "No milestones");
        require(expirationDays > 0, "Invalid expiration");

        // Verify milestones add up to 100%
        uint256 totalPercentage = 0;
        for (uint256 i = 0; i < milestonePercentages.length; i++) {
            totalPercentage += milestonePercentages[i];
        }
        require(totalPercentage == 10000, "Milestones must equal 100%");

        uint256 escrowId = nextEscrowId++;
        EscrowDetails storage escrow = escrows[escrowId];

        escrow.depositor = msg.sender;
        escrow.beneficiary = beneficiary;
        escrow.arbitrator = arbitrator != address(0) ? arbitrator : msg.sender;
        escrow.token = IERC20(token);
        escrow.totalAmount = totalAmount;
        escrow.escrowFee = (totalAmount * escrowFeePercent) / 10000;
        escrow.status = EscrowStatus.Pending;
        escrow.createdAt = block.timestamp;
        escrow.expiresAt = block.timestamp + (expirationDays * 1 days);
        escrow.dealId = dealId;
        escrow.dealDescription = dealDescription;

        // Create milestones
        for (uint256 i = 0; i < milestoneDescriptions.length; i++) {
            escrow.milestones.push(Milestone({
                description: milestoneDescriptions[i],
                percentage: milestonePercentages[i],
                completed: false,
                completedAt: 0
            }));
        }

        emit EscrowCreated(
            escrowId,
            msg.sender,
            beneficiary,
            token,
            totalAmount,
            dealId
        );

        return escrowId;
    }

    /**
     * @notice Fund the escrow (deposit funds)
     * @param escrowId Escrow ID to fund
     */
    function fundEscrow(uint256 escrowId)
        external
        whenNotPaused
        nonReentrant
    {
        EscrowDetails storage escrow = escrows[escrowId];
        require(escrow.depositor == msg.sender, "Not depositor");
        require(escrow.status == EscrowStatus.Pending, "Already funded");
        require(block.timestamp < escrow.expiresAt, "Expired");

        uint256 totalRequired = escrow.totalAmount + escrow.escrowFee;

        // Transfer tokens from depositor
        escrow.token.safeTransferFrom(msg.sender, address(this), totalRequired);

        // Transfer escrow fee to fee collector
        escrow.token.safeTransfer(feeCollector, escrow.escrowFee);

        escrow.status = EscrowStatus.Active;
        escrow.depositedAt = block.timestamp;

        emit EscrowFunded(escrowId, escrow.totalAmount, escrow.escrowFee);
    }

    /**
     * @notice Complete a milestone and release funds
     * @param escrowId Escrow ID
     * @param milestoneIndex Index of milestone to complete
     */
    function completeMilestone(uint256 escrowId, uint256 milestoneIndex)
        external
        onlyRole(ORACLE_ROLE)
        whenNotPaused
        nonReentrant
    {
        EscrowDetails storage escrow = escrows[escrowId];
        require(escrow.status == EscrowStatus.Active, "Not active");
        require(milestoneIndex < escrow.milestones.length, "Invalid milestone");
        require(!escrow.milestones[milestoneIndex].completed, "Already completed");

        // Mark milestone complete
        escrow.milestones[milestoneIndex].completed = true;
        escrow.milestones[milestoneIndex].completedAt = block.timestamp;

        // Calculate release amount
        uint256 releaseAmount = (escrow.totalAmount * escrow.milestones[milestoneIndex].percentage) / 10000;

        // Release funds to beneficiary
        escrow.token.safeTransfer(escrow.beneficiary, releaseAmount);
        escrow.releasedAmount += releaseAmount;

        emit MilestoneCompleted(escrowId, milestoneIndex, releaseAmount, escrow.beneficiary);

        // Check if all milestones complete
        bool allComplete = true;
        for (uint256 i = 0; i < escrow.milestones.length; i++) {
            if (!escrow.milestones[i].completed) {
                allComplete = false;
                break;
            }
        }

        if (allComplete) {
            escrow.status = EscrowStatus.Completed;
            escrow.completedAt = block.timestamp;
            emit EscrowCompleted(escrowId, escrow.releasedAmount);
        }
    }

    /**
     * @notice Raise a dispute
     * @param escrowId Escrow ID
     * @param reason Dispute reason
     */
    function raiseDispute(uint256 escrowId, string memory reason)
        external
        whenNotPaused
    {
        EscrowDetails storage escrow = escrows[escrowId];
        require(
            msg.sender == escrow.depositor || msg.sender == escrow.beneficiary,
            "Not authorized"
        );
        require(escrow.status == EscrowStatus.Active, "Not active");

        escrow.status = EscrowStatus.Disputed;

        emit EscrowDisputed(escrowId, msg.sender, reason);
    }

    /**
     * @notice Resolve a dispute (arbitrator only)
     * @param escrowId Escrow ID
     * @param depositorPercentage Percentage to return to depositor (basis points)
     * @param beneficiaryPercentage Percentage to send to beneficiary (basis points)
     */
    function resolveDispute(
        uint256 escrowId,
        uint256 depositorPercentage,
        uint256 beneficiaryPercentage
    )
        external
        onlyRole(ARBITRATOR_ROLE)
        whenNotPaused
        nonReentrant
    {
        EscrowDetails storage escrow = escrows[escrowId];
        require(escrow.status == EscrowStatus.Disputed, "Not disputed");
        require(
            depositorPercentage + beneficiaryPercentage == 10000,
            "Must equal 100%"
        );

        uint256 remainingAmount = escrow.totalAmount - escrow.releasedAmount;

        uint256 depositorAmount = (remainingAmount * depositorPercentage) / 10000;
        uint256 beneficiaryAmount = (remainingAmount * beneficiaryPercentage) / 10000;

        if (depositorAmount > 0) {
            escrow.token.safeTransfer(escrow.depositor, depositorAmount);
        }
        if (beneficiaryAmount > 0) {
            escrow.token.safeTransfer(escrow.beneficiary, beneficiaryAmount);
        }

        escrow.releasedAmount = escrow.totalAmount;
        escrow.status = EscrowStatus.Completed;
        escrow.completedAt = block.timestamp;

        emit DisputeResolved(escrowId, depositorAmount, beneficiaryAmount);
        emit EscrowCompleted(escrowId, escrow.releasedAmount);
    }

    /**
     * @notice Cancel escrow (only if not funded or expired)
     * @param escrowId Escrow ID
     */
    function cancelEscrow(uint256 escrowId)
        external
        whenNotPaused
        nonReentrant
    {
        EscrowDetails storage escrow = escrows[escrowId];
        require(msg.sender == escrow.depositor, "Not depositor");
        require(
            escrow.status == EscrowStatus.Pending ||
            (escrow.status == EscrowStatus.Active && block.timestamp >= escrow.expiresAt),
            "Cannot cancel"
        );

        uint256 refundAmount = escrow.totalAmount - escrow.releasedAmount;

        if (refundAmount > 0) {
            escrow.token.safeTransfer(escrow.depositor, refundAmount);
        }

        escrow.status = EscrowStatus.Cancelled;

        emit EscrowCancelled(escrowId, refundAmount);
    }

    // ============================================
    // VIEW FUNCTIONS
    // ============================================

    /**
     * @notice Get escrow details
     */
    function getEscrow(uint256 escrowId)
        external
        view
        returns (
            address depositor,
            address beneficiary,
            address token,
            uint256 totalAmount,
            uint256 releasedAmount,
            EscrowStatus status,
            uint256 milestoneCount
        )
    {
        EscrowDetails storage escrow = escrows[escrowId];
        return (
            escrow.depositor,
            escrow.beneficiary,
            address(escrow.token),
            escrow.totalAmount,
            escrow.releasedAmount,
            escrow.status,
            escrow.milestones.length
        );
    }

    /**
     * @notice Get milestone details
     */
    function getMilestone(uint256 escrowId, uint256 milestoneIndex)
        external
        view
        returns (
            string memory description,
            uint256 percentage,
            bool completed,
            uint256 completedAt
        )
    {
        EscrowDetails storage escrow = escrows[escrowId];
        require(milestoneIndex < escrow.milestones.length, "Invalid milestone");

        Milestone storage milestone = escrow.milestones[milestoneIndex];
        return (
            milestone.description,
            milestone.percentage,
            milestone.completed,
            milestone.completedAt
        );
    }

    /**
     * @notice Get all milestones for an escrow
     */
    function getMilestones(uint256 escrowId)
        external
        view
        returns (Milestone[] memory)
    {
        return escrows[escrowId].milestones;
    }

    // ============================================
    // ADMIN FUNCTIONS
    // ============================================

    /**
     * @notice Update escrow fee percentage
     * @param newFeePercent New fee in basis points (50 = 0.5%)
     */
    function setEscrowFeePercent(uint256 newFeePercent)
        external
        onlyRole(DEFAULT_ADMIN_ROLE)
    {
        require(newFeePercent <= 500, "Max 5%");
        escrowFeePercent = newFeePercent;
    }

    /**
     * @notice Update fee collector address
     */
    function setFeeCollector(address newFeeCollector)
        external
        onlyRole(DEFAULT_ADMIN_ROLE)
    {
        require(newFeeCollector != address(0), "Invalid address");
        feeCollector = newFeeCollector;
    }

    /**
     * @notice Emergency pause
     */
    function pause() external onlyRole(PAUSER_ROLE) {
        _pause();
    }

    /**
     * @notice Unpause
     */
    function unpause() external onlyRole(PAUSER_ROLE) {
        _unpause();
    }
}

contracts/core/Grain.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";

/**
 * @title Grain
 * @notice USDC-backed, auto-revaluing stablecoin for B2B settlements
 *
 * Unlike traditional stablecoins (fixed 1:1 peg), GRAIN price automatically
 * adjusts based on total Net Asset Value (NAV) of the Vault.
 *
 * Price Formula: GRAIN_PRICE = TOTAL_NAV / TOTAL_SUPPLY
 *
 * As Vault assets appreciate (treasury yield, asset appreciation, mortgage interest),
 * GRAIN price increases automatically. This creates network effects:
 * - More assets in Vault → Higher GRAIN price
 * - Higher GRAIN price → More demand for GRAIN
 * - More demand → More transactions → More fees → More assets
 *
 * Security Features:
 * - Circuit breaker (freeze price if anomaly detected)
 * - Multi-sig minting/burning
 * - Emergency pause mechanism
 * - 7-day audit process for major NAV changes
 */
contract Grain is ERC20, AccessControl, ReentrancyGuard, Pausable {
    // ============================================
    // ROLES
    // ============================================

    bytes32 public constant MINTER_ROLE = keccak256("MINTER_ROLE");
    bytes32 public constant BURNER_ROLE = keccak256("BURNER_ROLE");
    bytes32 public constant PAUSER_ROLE = keccak256("PAUSER_ROLE");
    bytes32 public constant ORACLE_ROLE = keccak256("ORACLE_ROLE");

    // ============================================
    // STATE VARIABLES
    // ============================================

    // Current GRAIN price in USD (18 decimals)
    // Example: 1.0417e18 = $1.0417 per GRAIN
    uint256 public grainPrice;

    // Total Net Asset Value backing GRAIN (18 decimals)
    // Sum of all Vault assets minus liabilities
    uint256 public totalNAV;

    // Circuit breaker state
    bool public circuitBreakerTriggered;
    uint256 public frozenPrice;
    uint256 public auditDeadline;

    // Revaluation tracking
    uint256 public lastRevaluationTime;
    uint256 public revaluationCount;

    // Minimum collateralization ratio (basis points)
    // 10000 = 100%, 11000 = 110%
    uint256 public minCollateralRatio = 11000; // 110%

    // ============================================
    // EVENTS
    // ============================================

    event GrainMinted(address indexed to, uint256 amount, uint256 price);
    event GrainBurned(address indexed from, uint256 amount, uint256 price);
    event PriceUpdated(uint256 oldPrice, uint256 newPrice, uint256 totalNAV, uint256 totalSupply);
    event CircuitBreakerTriggered(string reason, uint256 frozenPrice, uint256 auditDeadline);
    event CircuitBreakerReset(uint256 newPrice);
    event NAVUpdated(uint256 oldNAV, uint256 newNAV);

    // ============================================
    // CONSTRUCTOR
    // ============================================

    constructor(
        address admin,
        address vault,
        uint256 initialPrice
    ) ERC20("Grain", "GRAIN") {
        require(admin != address(0), "Invalid admin");
        require(vault != address(0), "Invalid vault");
        require(initialPrice > 0, "Invalid price");

        _grantRole(DEFAULT_ADMIN_ROLE, admin);
        _grantRole(MINTER_ROLE, vault);
        _grantRole(BURNER_ROLE, vault);
        _grantRole(PAUSER_ROLE, admin);
        _grantRole(ORACLE_ROLE, vault);

        grainPrice = initialPrice; // Start at $1.00 (1e18)
        lastRevaluationTime = block.timestamp;
    }

    // ============================================
    // MINTING & BURNING (Vault Only)
    // ============================================

    /**
     * @notice Mint new GRAIN tokens
     * @dev Only callable by Vault when:
     *      1. New assets deposited
     *      2. Escrow funded
     *      3. Mortgage issued
     *
     * @param to Recipient address
     * @param amount Amount of GRAIN to mint
     */
    function mint(address to, uint256 amount)
        external
        onlyRole(MINTER_ROLE)
        whenNotPaused
        nonReentrant
    {
        require(to != address(0), "Invalid recipient");
        require(amount > 0, "Invalid amount");
        require(!circuitBreakerTriggered, "Circuit breaker active");

        // Check collateralization ratio BEFORE minting
        uint256 newSupply = totalSupply() + amount;
        uint256 requiredNAV = (newSupply * grainPrice * minCollateralRatio) / 10000 / 1e18;
        require(totalNAV >= requiredNAV, "Insufficient collateral");

        _mint(to, amount);

        emit GrainMinted(to, amount, grainPrice);
    }

    /**
     * @notice Burn GRAIN tokens
     * @dev Only callable by Vault when:
     *      1. User redeems GRAIN for USDC
     *      2. Escrow released
     *      3. Mortgage paid off
     *
     * @param from Address to burn from
     * @param amount Amount to burn
     */
    function burn(address from, uint256 amount)
        external
        onlyRole(BURNER_ROLE)
        whenNotPaused
        nonReentrant
    {
        require(from != address(0), "Invalid address");
        require(amount > 0, "Invalid amount");
        require(balanceOf(from) >= amount, "Insufficient balance");

        _burn(from, amount);

        emit GrainBurned(from, amount, grainPrice);
    }

    // ============================================
    // PRICE REVALUATION (Oracle Only)
    // ============================================

    /**
     * @notice Update GRAIN price based on current NAV
     * @dev Called daily by Vault oracle after calculating total NAV
     *
     * Formula: newPrice = totalNAV / totalSupply
     *
     * Circuit breakers trigger if:
     * 1. Price drops > 5%
     * 2. NAV declines > 10%
     * 3. Collateralization < 100%
     *
     * @param newNAV Total Net Asset Value in USD (18 decimals)
     */
    function updateNAV(uint256 newNAV)
        external
        onlyRole(ORACLE_ROLE)
        whenNotPaused
    {
        require(newNAV > 0, "Invalid NAV");
        require(!circuitBreakerTriggered, "Circuit breaker active");

        uint256 oldNAV = totalNAV;
        totalNAV = newNAV;

        // Calculate new GRAIN price
        uint256 supply = totalSupply();
        if (supply == 0) {
            // No GRAIN issued yet, keep initial price
            emit NAVUpdated(oldNAV, newNAV);
            return;
        }

        uint256 newPrice = (newNAV * 1e18) / supply;
        uint256 oldPrice = grainPrice;

        // CIRCUIT BREAKER #1: Price drop > 5%
        if (newPrice < oldPrice) {
            uint256 priceDrop = ((oldPrice - newPrice) * 10000) / oldPrice; // basis points
            if (priceDrop > 500) { // 5%
                _triggerCircuitBreaker("Price drop >5%", oldPrice);
                return;
            }
        }

        // CIRCUIT BREAKER #2: NAV decline > 10%
        if (newNAV < oldNAV) {
            uint256 navDrop = ((oldNAV - newNAV) * 10000) / oldNAV;
            if (navDrop > 1000) { // 10%
                _triggerCircuitBreaker("NAV decline >10%", oldPrice);
                return;
            }
        }

        // CIRCUIT BREAKER #3: Undercollateralized
        uint256 collateralRatio = (newNAV * 10000) / (supply * newPrice / 1e18);
        if (collateralRatio < 10000) { // Less than 100%
            _triggerCircuitBreaker("Undercollateralized", oldPrice);
            return;
        }

        // All checks passed, update price
        grainPrice = newPrice;
        lastRevaluationTime = block.timestamp;
        revaluationCount++;

        emit PriceUpdated(oldPrice, newPrice, newNAV, supply);
        emit NAVUpdated(oldNAV, newNAV);
    }

    /**
     * @notice Trigger circuit breaker and freeze price
     * @dev Initiates 7-day audit process
     */
    function _triggerCircuitBreaker(string memory reason, uint256 _frozenPrice) internal {
        circuitBreakerTriggered = true;
        frozenPrice = _frozenPrice;
        auditDeadline = block.timestamp + 7 days;

        _pause(); // Pause all minting/burning

        emit CircuitBreakerTriggered(reason, frozenPrice, auditDeadline);
    }

    /**
     * @notice Reset circuit breaker after audit
     * @dev Only callable by admin after 7-day audit complete
     *
     * @param newPrice Audited GRAIN price
     * @param newNAV Audited total NAV
     */
    function resetCircuitBreaker(uint256 newPrice, uint256 newNAV)
        external
        onlyRole(DEFAULT_ADMIN_ROLE)
    {
        require(circuitBreakerTriggered, "Not triggered");
        require(block.timestamp >= auditDeadline, "Audit not complete");
        require(newPrice > 0 && newNAV > 0, "Invalid values");

        // Verify new values are reasonable (within 20% of frozen values)
        uint256 supply = totalSupply();
        if (supply > 0) {
            uint256 expectedPrice = (newNAV * 1e18) / supply;
            uint256 priceDiff = newPrice > expectedPrice
                ? ((newPrice - expectedPrice) * 10000) / expectedPrice
                : ((expectedPrice - newPrice) * 10000) / expectedPrice;
            require(priceDiff <= 2000, "Price deviation >20%");
        }

        grainPrice = newPrice;
        totalNAV = newNAV;
        circuitBreakerTriggered = false;
        frozenPrice = 0;
        auditDeadline = 0;

        _unpause(); // Resume minting/burning

        emit CircuitBreakerReset(newPrice);
    }

    // ============================================
    // ADMIN FUNCTIONS
    // ============================================

    /**
     * @notice Emergency pause (stops all transfers, minting, burning)
     */
    function pause() external onlyRole(PAUSER_ROLE) {
        _pause();
    }

    /**
     * @notice Unpause
     */
    function unpause() external onlyRole(PAUSER_ROLE) {
        _unpause();
    }

    /**
     * @notice Update minimum collateralization ratio
     * @param newRatio New ratio in basis points (10000 = 100%)
     */
    function setMinCollateralRatio(uint256 newRatio)
        external
        onlyRole(DEFAULT_ADMIN_ROLE)
    {
        require(newRatio >= 10000 && newRatio <= 15000, "Invalid ratio");
        minCollateralRatio = newRatio;
    }

    // ============================================
    // VIEW FUNCTIONS
    // ============================================

    /**
     * @notice Get current collateralization ratio
     * @return Ratio in basis points (10000 = 100%)
     */
    function getCollateralRatio() external view returns (uint256) {
        uint256 supply = totalSupply();
        if (supply == 0) return type(uint256).max;

        uint256 totalValue = supply * grainPrice / 1e18;
        return (totalNAV * 10000) / totalValue;
    }

    /**
     * @notice Get GRAIN price in USD
     * @return Price with 18 decimals (1e18 = $1.00)
     */
    function getPrice() external view returns (uint256) {
        return circuitBreakerTriggered ? frozenPrice : grainPrice;
    }

    /**
     * @notice Check if circuit breaker is active
     */
    function isCircuitBreakerActive() external view returns (bool) {
        return circuitBreakerTriggered;
    }

    /**
     * @notice Get time until audit deadline
     * @return Seconds remaining (0 if not triggered)
     */
    function getAuditTimeRemaining() external view returns (uint256) {
        if (!circuitBreakerTriggered) return 0;
        if (block.timestamp >= auditDeadline) return 0;
        return auditDeadline - block.timestamp;
    }

    // ============================================
    // OVERRIDE REQUIRED BY PAUSABLE
    // ============================================

    /**
     * @dev Hook override for ERC20 _update (replaces _beforeTokenTransfer in v5)
     * @notice Ensures all token transfers respect the pause state
     */
    function _update(
        address from,
        address to,
        uint256 amount
    ) internal override whenNotPaused {
        super._update(from, to, amount);
    }
}

contracts/core/Vault.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";

/**
 * @title Vault
 * @notice Treasury holding USDC reserves + tracking all downstream assets
 * @dev Multi-sig controlled, fully auditable, real-time NAV calculation
 *
 * Security features:
 * - Multi-signature wallet control
 * - Role-based access control
 * - Reentrancy protection
 * - Emergency pause mechanism
 * - Comprehensive event logging
 *
 * Asset tracking:
 * - Liquid reserves (USDC, cash, money market, treasuries)
 * - Float & in-transit (pending escrows, ACH, wires)
 * - Physical assets (inventory, equipment, real estate)
 * - Investment positions (bonds, equities, alternatives)
 * - Receivables (invoices, loans, pending fees)
 */
contract Vault is AccessControl, ReentrancyGuard, Pausable {
    bytes32 public constant WITHDRAWER_ROLE = keccak256("WITHDRAWER_ROLE");
    bytes32 public constant ORACLE_ROLE = keccak256("ORACLE_ROLE");
    bytes32 public constant PAUSER_ROLE = keccak256("PAUSER_ROLE");

    IERC20 public immutable usdc;

    // Vault statistics
    uint256 public totalDeposits;
    uint256 public totalWithdrawals;

    // Asset categories (tracked off-chain, verified on-chain)
    struct AssetBreakdown {
        uint256 liquidReserves;         // USDC + cash + money market + treasuries
        uint256 floatInTransit;         // Pending escrows + ACH + wires
        uint256 physicalAssets;         // Inventory + equipment + real estate
        uint256 investmentPositions;    // Bonds + equities + alternatives
        uint256 receivables;            // Invoices + loans + fees (probability-adjusted)
        uint256 lastUpdated;            // Timestamp of last update
    }

    AssetBreakdown public assets;

    // Circuit breaker state
    bool public circuitBreakerTriggered;
    uint256 public frozenGrainPrice; // Price frozen when circuit breaker triggered
    uint256 public auditDeadline;    // Timestamp when audit must be complete

    // Historical NAV tracking (for circuit breaker)
    uint256 public lastNAV;
    uint256 public yesterdayHighPrice;

    // Events
    event Deposit(address indexed from, uint256 amount, uint256 timestamp);
    event Withdrawal(address indexed to, uint256 amount, uint256 timestamp);
    event AssetsUpdated(
        uint256 liquidReserves,
        uint256 floatInTransit,
        uint256 physicalAssets,
        uint256 investmentPositions,
        uint256 receivables,
        uint256 totalNAV
    );
    event CircuitBreakerTriggered(
        string reason,
        uint256 frozenPrice,
        uint256 navAtTrigger,
        uint256 auditDeadline
    );
    event CircuitBreakerResolved(
        uint256 newGrainPrice,
        uint256 newNAV,
        uint256 resolvedAt
    );
    event NAVCalculated(uint256 nav, uint256 timestamp);

    constructor(address _usdc) {
        require(_usdc != address(0), "Invalid USDC address");
        usdc = IERC20(_usdc);

        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(WITHDRAWER_ROLE, msg.sender);
        _grantRole(ORACLE_ROLE, msg.sender);
        _grantRole(PAUSER_ROLE, msg.sender);

        // Initialize asset breakdown
        assets.lastUpdated = block.timestamp;
    }

    /**
     * @notice Deposit USDC into Vault
     * @param amount Amount of USDC to deposit
     */
    function deposit(uint256 amount) external nonReentrant whenNotPaused {
        require(amount > 0, "Amount must be positive");

        require(
            usdc.transferFrom(msg.sender, address(this), amount),
            "USDC transfer failed"
        );

        totalDeposits += amount;
        emit Deposit(msg.sender, amount, block.timestamp);
    }

    /**
     * @notice Withdraw USDC from Vault (requires WITHDRAWER_ROLE)
     * @param to Recipient address
     * @param amount Amount to withdraw
     */
    function withdraw(address to, uint256 amount)
        external
        onlyRole(WITHDRAWER_ROLE)
        nonReentrant
        whenNotPaused
    {
        require(to != address(0), "Invalid recipient");
        require(amount > 0, "Amount must be positive");
        require(usdc.balanceOf(address(this)) >= amount, "Insufficient balance");

        require(
            usdc.transfer(to, amount),
            "USDC transfer failed"
        );

        totalWithdrawals += amount;
        emit Withdrawal(to, amount, block.timestamp);
    }

    /**
     * @notice Update asset breakdown (called by oracle)
     * @dev This is called periodically (every 5 min) by backend service
     * @param _liquidReserves USDC + cash + money market + treasuries
     * @param _floatInTransit Pending escrows + ACH + wires
     * @param _physicalAssets Inventory + equipment + real estate
     * @param _investmentPositions Bonds + equities + alternatives
     * @param _receivables Invoices + loans + fees (probability-adjusted)
     */
    function updateAssets(
        uint256 _liquidReserves,
        uint256 _floatInTransit,
        uint256 _physicalAssets,
        uint256 _investmentPositions,
        uint256 _receivables
    ) external onlyRole(ORACLE_ROLE) {
        assets.liquidReserves = _liquidReserves;
        assets.floatInTransit = _floatInTransit;
        assets.physicalAssets = _physicalAssets;
        assets.investmentPositions = _investmentPositions;
        assets.receivables = _receivables;
        assets.lastUpdated = block.timestamp;

        uint256 totalNAV = getTotalNAV();

        emit AssetsUpdated(
            _liquidReserves,
            _floatInTransit,
            _physicalAssets,
            _investmentPositions,
            _receivables,
            totalNAV
        );

        emit NAVCalculated(totalNAV, block.timestamp);

        // Update historical tracking
        lastNAV = totalNAV;
    }

    /**
     * @notice Get current USDC balance in Vault
     */
    function getUSDCBalance() external view returns (uint256) {
        return usdc.balanceOf(address(this));
    }

    /**
     * @notice Get total liquid reserves
     */
    function getLiquidReserves() external view returns (uint256) {
        return assets.liquidReserves;
    }

    /**
     * @notice Get total NAV (sum of all assets minus liabilities)
     * @dev Liabilities assumed to be zero for v1 (no loans)
     * @return Total net asset value in USD (6 decimals, USDC standard)
     */
    function getTotalNAV() public view returns (uint256) {
        uint256 totalAssets =
            assets.liquidReserves +
            assets.floatInTransit +
            assets.physicalAssets +
            assets.investmentPositions +
            assets.receivables;

        // In v1, no liabilities. In v2+, subtract liabilities here.
        uint256 liabilities = 0;

        return totalAssets - liabilities;
    }

    /**
     * @notice Get asset breakdown
     */
    function getAssetBreakdown()
        external
        view
        returns (
            uint256 liquidReserves,
            uint256 floatInTransit,
            uint256 physicalAssets,
            uint256 investmentPositions,
            uint256 receivables,
            uint256 lastUpdated
        )
    {
        return (
            assets.liquidReserves,
            assets.floatInTransit,
            assets.physicalAssets,
            assets.investmentPositions,
            assets.receivables,
            assets.lastUpdated
        );
    }

    /**
     * @notice Trigger circuit breaker (emergency stop)
     * @param reason Human-readable reason for triggering
     * @param _frozenPrice GRAIN price to freeze at
     */
    function triggerCircuitBreaker(string memory reason, uint256 _frozenPrice)
        external
        onlyRole(PAUSER_ROLE)
    {
        require(!circuitBreakerTriggered, "Circuit breaker already active");

        circuitBreakerTriggered = true;
        frozenGrainPrice = _frozenPrice;
        auditDeadline = block.timestamp + 7 days; // 7-day audit period

        uint256 navAtTrigger = getTotalNAV();

        emit CircuitBreakerTriggered(
            reason,
            _frozenPrice,
            navAtTrigger,
            auditDeadline
        );

        // Pause all operations
        _pause();
    }

    /**
     * @notice Resolve circuit breaker (after 7-day audit)
     * @param newGrainPrice New GRAIN price after audit
     * @dev Requires multi-sig approval (2-of-3 founders)
     */
    function resolveCircuitBreaker(uint256 newGrainPrice)
        external
        onlyRole(DEFAULT_ADMIN_ROLE)
    {
        require(circuitBreakerTriggered, "Circuit breaker not active");
        require(block.timestamp >= auditDeadline, "Audit period not complete");

        circuitBreakerTriggered = false;
        uint256 newNAV = getTotalNAV();

        emit CircuitBreakerResolved(
            newGrainPrice,
            newNAV,
            block.timestamp
        );

        // Unpause operations
        _unpause();
    }

    /**
     * @notice Set yesterday's high price (for circuit breaker reference)
     * @param price GRAIN price (yesterday's high)
     */
    function setYesterdayHighPrice(uint256 price)
        external
        onlyRole(ORACLE_ROLE)
    {
        yesterdayHighPrice = price;
    }

    /**
     * @notice Emergency pause (stops all deposits/withdrawals)
     */
    function pause() external onlyRole(PAUSER_ROLE) {
        _pause();
    }

    /**
     * @notice Unpause
     */
    function unpause() external onlyRole(DEFAULT_ADMIN_ROLE) {
        _unpause();
    }
}

